import{_ as o,o as a,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"篇462｜龙珠·女子角色处境：布尔玛等角色的工具化","description":"","frontmatter":{"title":"篇462｜龙珠·女子角色处境：布尔玛等角色的工具化","no":462,"module":2,"tags":["诸天对标","龙珠","女子角色","布尔玛","琪琪","工具化","万族共和"],"related":["08-人人有路保障体系","51-人族定位与特质","36-社会结构与阶层流动"]},"headers":[],"relativePath":"zh/462_模块2-龙珠-女子角色处境-布尔玛等角色的工具化.md","filePath":"zh/462_模块2-龙珠-女子角色处境-布尔玛等角色的工具化.md"}'),e={name:"zh/462_模块2-龙珠-女子角色处境-布尔玛等角色的工具化.md"};function i(n,t,s,h,u,d){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="篇462-龙珠·女子角色处境-布尔玛等角色的工具化" tabindex="-1">篇462｜龙珠·女子角色处境：布尔玛等角色的工具化 <a class="header-anchor" href="#篇462-龙珠·女子角色处境-布尔玛等角色的工具化" aria-label="Permalink to &quot;篇462｜龙珠·女子角色处境：布尔玛等角色的工具化&quot;">​</a></h1><blockquote><p>所属模块：模块二·诸天对标批判库｜系列：龙珠体系全套拆解（第31篇·文明分析4）｜对标地基：文档08、51、36</p></blockquote><h2 id="引言-当最聪明的女人只负责-造飞船" tabindex="-1">引言：当最聪明的女人只负责&quot;造飞船&quot; <a class="header-anchor" href="#引言-当最聪明的女人只负责-造飞船" aria-label="Permalink to &quot;引言：当最聪明的女人只负责&quot;造飞船&quot;&quot;">​</a></h2><p>布尔玛是龙珠里最聪明的人：她发明龙珠雷达、造时光机、造飞船、是万能胶囊公司的继承人。但她的全部戏份，都是&quot;给悟空提供工具&quot;——她从不修炼、从不战斗、从不参与宇宙级决策。琪琪是悟空的妻子，她的全部戏份是&quot;希望悟饭别打架&quot;。兰奇、人造人18号、比迪丽……龙珠的女子角色，要么是工具人，要么是家属。本文以万族共和公理为核心，拆解龙珠女子角色的工具化处境。</p><p>本文评判底座为六大顶层公理（反掠夺主义公理、万族共和公理、集体升维公理、因果自律公理、法则优先公理、众生全员无限均等法则）与五大强制核心（反能级浪费、反掠夺、唐罗上限对比、万族全覆盖、超多元全开放），其中法则优先公理为核心。众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、该体系强者的「能级浪费」解析" tabindex="-1">一、该体系强者的「能级浪费」解析 <a class="header-anchor" href="#一、该体系强者的「能级浪费」解析" aria-label="Permalink to &quot;一、该体系强者的「能级浪费」解析&quot;">​</a></h2><p>女子角色的能级浪费：</p><ul><li><strong>布尔玛的智商浪费</strong>：她本可成为地球最伟大的科学家，却被锁在&quot;造飞船给悟空用&quot;的位置</li><li><strong>18号的战力浪费</strong>：人造人18号本是顶级战力，后期嫁给克林后彻底退出战斗</li><li><strong>比迪丽的天赋浪费</strong>：比迪丽本可成为优秀修炼者，后期戏份为零</li><li><strong>结论</strong>：龙珠的女子角色，无论智商还是战力，全部被工具化</li></ul><h2 id="二、该文明为何必然历史倒退" tabindex="-1">二、该文明为何必然历史倒退 <a class="header-anchor" href="#二、该文明为何必然历史倒退" aria-label="Permalink to &quot;二、该文明为何必然历史倒退&quot;">​</a></h2><p>女子角色工具化如何喂养历史倒退：</p><ol><li><strong>一半人口被边缘化</strong>：龙珠世界的英雄叙事全部围绕男性展开，女子角色无主角位</li><li><strong>知识不共享</strong>：布尔玛的科技知识从不教材化，她死后地球科技断档</li><li><strong>修炼路径性别化</strong>：女子修炼者（18号、比迪丽）后期全部退居家庭，修炼路径不完整</li></ol><h2 id="三、主角掠夺思维深度拆解" tabindex="-1">三、主角掠夺思维深度拆解 <a class="header-anchor" href="#三、主角掠夺思维深度拆解" aria-label="Permalink to &quot;三、主角掠夺思维深度拆解&quot;">​</a></h2><p>悟空在女子角色工具化中的角色：</p><ul><li><strong>接受工具化</strong>：悟空从不质疑&quot;为什么布尔玛只负责造飞船&quot;，他默认这是天经地义</li><li><strong>对妻子的无视</strong>：琪琪希望悟饭读书，悟空从不支持也不反对，他默认&quot;打就行&quot;</li><li><strong>不培养女修炼者</strong>：悟空从未系统培养任何女性修炼者，地球的英雄叙事全是男性</li></ul><h2 id="四、对比锚点共生的完善替代方案" tabindex="-1">四、对比锚点共生的完善替代方案 <a class="header-anchor" href="#四、对比锚点共生的完善替代方案" aria-label="Permalink to &quot;四、对比锚点共生的完善替代方案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>龙珠女子工具化</th><th>锚点共生替代方案</th></tr></thead><tbody><tr><td>布尔玛=造飞船工具</td><td>共生教育体系（文档037）：女性修炼者与男性同权</td></tr><tr><td>18号战力浪费</td><td>万族五大谱系平等：任何性别都有完整修炼路径</td></tr><tr><td>比迪丽天赋浪费</td><td>三百套本源修炼体系全开放，女性修炼者有自己的轨道</td></tr><tr><td>琪琪=家属</td><td>人人有路保障体系（文档08）：女性不被锁在家庭角色</td></tr><tr><td>英雄叙事全男性</td><td>万族共和：女性修炼者可成为锚点议事会成员</td></tr></tbody></table><h2 id="五、该体系纳入求索域模拟复盘方案" tabindex="-1">五、该体系纳入求索域模拟复盘方案 <a class="header-anchor" href="#五、该体系纳入求索域模拟复盘方案" aria-label="Permalink to &quot;五、该体系纳入求索域模拟复盘方案&quot;">​</a></h2><ol><li><strong>建模</strong>：求索沉淀域复刻龙珠世界，注入&quot;女性修炼者与男性同权&quot;变量</li><li><strong>变量</strong>：注入&quot;布尔玛系统修炼&quot;&quot;18号继续战斗&quot;&quot;比迪丽成为顶级修炼者&quot;</li><li><strong>观测</strong>：统计地球女性修炼者出路率、英雄叙事中女性占比</li><li><strong>复盘</strong>：输出《龙珠女子角色工具化代价报告》，量化&quot;一半人口被边缘化&quot;对文明的损失</li></ol><h2 id="六、设定自洽度-吃书烂尾风险评估" tabindex="-1">六、设定自洽度/吃书烂尾风险评估 <a class="header-anchor" href="#六、设定自洽度-吃书烂尾风险评估" aria-label="Permalink to &quot;六、设定自洽度/吃书烂尾风险评估&quot;">​</a></h2><ul><li><strong>女子角色设定自洽度</strong>：低（18号从顶级反派到家庭主妇，比迪丽从超级英雄到母亲，角色弧光断裂）</li><li><strong>万族共和自洽度预期</strong>：高（女性修炼者有完整路径，不被工具化）</li><li><strong>吃书烂尾风险</strong>：中（女子角色在多部续作间定位漂移）</li><li><strong>主角唯一性依赖度</strong>：高——英雄叙事全系于男性主角，女性无主角位</li></ul><p><strong>新旧宇宙资源对标</strong>：旧宇宙资源与大道是有限的，必然掠夺内卷；锚点共生人人自带无限本源，掠夺失去意义。</p><h2 id="五大核心落点" tabindex="-1">五大核心落点 <a class="header-anchor" href="#五大核心落点" aria-label="Permalink to &quot;五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：布尔玛的智商、18号的战力、比迪丽的天赋全部被工具化</li><li><strong>反掠夺</strong>：一半人口被边缘化，知识不共享、修炼路径不完整</li><li><strong>唐罗上限对比</strong>：唐罗至少没有明显的女性边缘化，龙珠的女子角色工具化更严重</li><li><strong>万族全覆盖</strong>：女性作为万族一半，必须纳入共和，不做工具人</li><li><strong>超多元全开放</strong>：女性修炼者有完整路径后，龙珠世界的修炼者基数翻倍</li><li><strong>众生全员无限均等</strong>：基础无限之力人人自带，佛系保有保底、卷王可叠加更高，无限本源消弭掠夺动机，掠夺内卷从根上失去意义</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>龙珠的女子角色工具化，不是鸟山明一个人的偏见，是那个时代少年漫的结构性通病。但衡元宙的评判不看时代背景，只看结构：当最聪明的女人只负责造飞船、当最强的人造人只负责结婚，这个文明就浪费了一半的人口潜力。让布尔玛修炼、让18号战斗、让比迪丽成为顶级修炼者——龙珠世界才真正配得上&quot;万族&quot;二字。</p><p>补充一层：布尔玛的处境尤其可惜。她是龙珠里唯一有&quot;科学家&quot;身份的角色，她的发明（龙珠雷达、胶囊飞船、时光机）每次都在剧情关键节点救场——但她从不被当作&quot;决策者&quot;。时光机是她造的，但用不用、什么时候用，全由悟空和贝吉塔决定。她的智力成果被男角色拿去使用，她本人却不参与决策。这在锚点共生的万族共和框架下是不可接受的：知识贡献者必须参与决策，否则就是智力层面的被剥夺。</p><p>说到底，本篇所述的龙珠·女子角色处境·布尔玛等角色的工具化并非孤例——其因果与能级留痕全程纳入阿赖耶网络备案、可溯可校。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./461_模块2-龙珠-弗利萨军团-掠夺式文明的极端形态.html">篇461·弗利萨军团</a> · <a href="./463_模块2-龙珠-少年成长机制-天才的战斗宿命.html">篇463·少年成长机制</a> · <a href="./../wanling-hengmao-origin-universe-archive/docs/zh/08-人人有路保障体系.html">08-人人有路保障体系</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',29)])])}const _=o(e,[["render",i]]);export{q as __pageData,_ as default};
